tool_input.command:
$env:PYTHONIOENCODING='utf-8'
Write-Output "== 主目录各 md 文件里的'专用标准'/按市场标准 说法 =="
Get-ChildItem '分析产出' -Filter '*.md' | ForEach-Object {
  $hits = Select-String -Path $_.FullName -Pattern '专用标准|深市.*标准|沪市.*标准|深市专用|沪深.*专用' 
  if($hits){ "---- $($_.Name) ----"; $hits | Select-Object -First 8 | ForEach-Object {"  $($_.LineNumber): $($_.Line.Trim().Substring(0,[Math]::Min(80,$_.Line.Trim().Length)))"} }
}

Copy-Item '分析产出\screen_sh.py' '分析产出\screen_all.py' -Force
$env:PYTHONIOENCODING='utf-8'
Select-String -Path '分析产出\screen_all.py' -Pattern "^OUT =|^DETAIL =|^FUNNEL =|^LAKE =|exchange='SH'|board.map|科创板" | ForEach-Object {"$($_.LineNumber): $($_.Line.Trim())"}
